public class Parser {
    protected void processProperties(Properties properties) throws ParseException {
        if (properties == null)
            return;

        for (Enumeration e = properties.propertyNames(); e.hasMoreElements();) {
            String option = e.nextElement().toString();

            Option opt = options.getOption(option);
            if (opt == null)
                throw new UnrecognizedOptionException("Default option wasn't defined", option);

            // if the option is part of a group, check if another option of the group has been selected
            OptionGroup group = options.getOptionGroup(opt);
            boolean selected = group != null && group.getSelected() != null;

            if (!cmd.hasOption(option) && !selected)
                processOption(properties, opt);
        }
    }

    private void processOption(Properties properties, Option opt) throws ParseException {
        String value = properties.getProperty(opt.getOpt());

        if (opt.hasArg()) {
            if (opt.getValues() == null || opt.getValues().length == 0) {
                try {
                    opt.addValueForProcessing(value);
                } catch (RuntimeException exp) {
                    // ignore
                }
            }
        } else if (!("yes".equalsIgnoreCase(value)
                || "true".equalsIgnoreCase(value)
                || "1".equalsIgnoreCase(value))) {
            return;
        }

        cmd.addOption(opt);
        updateRequiredOptions(opt);
    }
}
